{"cards": [{"node_code": "N_acb566e00b12f0d4", "definition": "研究交通运输领域的基础经济规律、制度安排、价格机制及企业经营管理理论，涵盖从宏观政策规制到微观企业运营的系统性经济分析框架。", "boundary": "本节点聚焦于“理论”与“机制”，即解释运输经济现象的抽象模型、制度逻辑及一般性管理原则。区别于“世界各国概况”（侧重具体国家/地区的实证数据与现状描述）和“数字交通与平台经济”（侧重特定技术形态下的新经济模式）。若内容涉及具体国家的政策实施细节或统计数据，应归入“世界各国概况”；若涉及网约车、货运平台等特定数字业态，应归入“数字交通与平台经济”。", "includes": ["运输业计划、管理体制及公共服务规制理论", "交通基础设施投融资、项目经济评价及资产经营理论", "运输价格、成本、利润形成机制及运输企业组织与经营管理理论"], "excludes": ["具体国家或地区的交通运输现状、统计数据及政策实施案例（归入世界各国概况）", "基于互联网平台的共享交通、运输电子商务及数据要素价值分析（归入数字交通与平台经济）", "绿色交通特有的碳交易、环境外部性内部化机制（归入绿色交通经济）"], "sibling_distinctions": [{"other_code": "N_6bccb90895e40842", "rule": "本节点提供普适性的经济理论框架与机制分析；兄弟节点侧重特定地理区域（如中国、世界）的交通运输概况、具体政策实践及历史数据。"}, {"other_code": "N_a983b547b259a5db", "rule": "本节点涵盖传统运输经济及一般性企业管理理论；兄弟节点专门研究数字技术驱动下的平台经济、共享出行及运输电商等新兴业态。"}, {"other_code": "N_ca08c3043a6efc4f", "rule": "本节点关注一般性的成本、利润及资源配置效率；兄弟节点专门聚焦于环境外部性、碳经济及绿色发展的特定经济问题。"}], "cross_boundary_rule": "当理论分析结合具体国家案例时，若侧重理论推导与机制验证，主挂载本节点；若侧重该国特定政策背景下的实证描述，主挂载世界各国概况。"}, {"node_code": "N_6bccb90895e40842", "definition": "按地理区域（世界、中国等）梳理交通运输发展的概况、政策实践、管理体制、建设成就及历史沿革，侧重特定区域的经济特征与实证描述。", "boundary": "本节点核心在于“地域性”与“概况性”，即对特定国家或地区交通运输经济现状、政策执行、基础设施发展及历史变迁的描述与分析。区别于“交通运输经济理论”（侧重普适性理论模型）和“数字交通与平台经济”（侧重特定技术业态）。若内容是全球性的理论探讨，归入理论节点；若涉及具体国家的政策文件、统计数据、发展成就或历史事件，归入本节点。", "includes": ["世界及主要国家的交通运输政策、管理体制及建设发展概况", "特定区域的国际联合运输、条约协定及国际组织活动", "中国及地方的交通运输方针政策、价格成本实践、企业组织管理及交通史"], "excludes": ["不依赖特定地域的普适性运输经济理论、定价模型或管理原则（归入交通运输经济理论）", "全球范围内通用的数字平台经济模式分析（归入数字交通与平台经济）", "纯粹的技术工程标准或车辆技术参数（归入相关工程技术节点）"], "sibling_distinctions": [{"other_code": "N_acb566e00b12f0d4", "rule": "本节点侧重“是什么”（特定区域的现状、政策、数据）；兄弟节点侧重“为什么”和“如何运作”（普适性的经济规律、机制、理论模型）。"}, {"other_code": "N_a983b547b259a5db", "rule": "本节点包含各国数字交通发展的概况与政策；兄弟节点聚焦于数字交通与平台经济本身的商业模式、技术架构及经济效应分析。"}], "cross_boundary_rule": "涉及某国具体政策对运输经济影响的实证研究，若以该国为背景案例，主挂载本节点；若旨在提炼通用政策效果理论，主挂载交通运输经济理论。"}, {"node_code": "N_a983b547b259a5db", "definition": "研究数字技术驱动下的交通运输新业态经济，涵盖平台经济、共享交通、运输电子商务、商务智能决策及交通数据要素的价值创造与机制分析。", "boundary": "本节点聚焦于“数字化”与“平台化”带来的经济变革，关注算法匹配、双边市场、数据资产化及电商模式在运输领域的应用。区别于“交通运输经济理论”（传统运输经济机制）和“世界各国概况”（地域性描述）。若内容涉及传统运输企业的数字化转型管理，但核心仍是传统管理理论，可归入理论节点；若核心是平台机制、数据价值或电商模式，归入本节点。", "includes": ["平台经济与共享交通的商业模式、定价机制及市场结构分析", "运输电子商务、电商系统分析及运输商务智能决策", "交通数据要素的价值评估、流通机制及数据驱动的经济效应"], "excludes": ["传统运输方式（如铁路、公路）的基础设施投融资及一般性成本利润理论（归入交通运输经济理论）", "特定国家数字交通发展的政策概况与统计数据（归入世界各国概况）", "绿色交通中的碳交易机制及环境经济分析（归入绿色交通经济）"], "sibling_distinctions": [{"other_code": "N_acb566e00b12f0d4", "rule": "本节点专门研究数字平台、共享经济及数据要素等新兴形态；兄弟节点涵盖传统运输经济理论及一般性企业经营管理理论。"}, {"other_code": "N_6bccb90895e40842", "rule": "本节点分析数字交通经济的通用模式与机制；兄弟节点描述特定国家或地区在数字交通领域的政策实施与发展现状。"}], "cross_boundary_rule": "涉及数字平台对传统运输市场结构影响的理论分析，主挂载本节点；若侧重某国对网约车等平台的监管政策描述，主挂载世界各国概况。"}]}
